// swift-tools-version: 6.0
// Menu bar app for wgd. Build with `make`: it compiles the Rust core
// (crates/wgd-bar-ffi), generates the bindings into Sources/ and then runs
// `swift build`. A plain `swift build` without that step does not compile.

import PackageDescription

let rustLib = "../../target/release"

let package = Package(
    name: "WgdBar",
    platforms: [.macOS(.v14)],
    targets: [
        // Header and modulemap generated by UniFFI; the module name is the
        // one the generated Swift file imports.
        .systemLibrary(name: "wgd_bar_ffiFFI"),
        .executableTarget(
            name: "WgdBar",
            dependencies: ["wgd_bar_ffiFFI"],
            linkerSettings: [
                .unsafeFlags(["-L\(rustLib)"]),
                .linkedLibrary("wgd_bar_ffi"),
                // Used by the wgd library (admin authorization).
                .linkedFramework("Security"),
            ]
        ),
    ]
)
